import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as t,c as n,o as l,ag as e,G as o}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Tailscale source code walkthrough","description":"How one Tailscale connection gets built in the code: the CLI calls LocalAPI over a local socket, LocalBackend loads the network map sent down by the coordination server into wgengine, and magicsock chooses between a direct connection and a DERP relay. This page reads the source code, and every conclusion comes with a permalink to a pinned commit.","frontmatter":{"title":"Tailscale source code walkthrough","description":"How one Tailscale connection gets built in the code: the CLI calls LocalAPI over a local socket, LocalBackend loads the network map sent down by the coordination server into wgengine, and magicsock chooses between a direct connection and a DERP relay. This page reads the source code, and every conclusion comes with a permalink to a pinned commit.","domain":"product","tags":["source-code","mesh-vpn","go","tailscale"],"role":"deep-dive","pageClass":"wide-figures","source_revision":"da6276d77025ee2bce288c4ccf07b35e14f253a7"},"headers":[],"relativePath":"products/tailscale/source.md","filePath":"products/tailscale/source.md","lastUpdated":1795592559000}'),h={name:"products/tailscale/source.md"};function r(d,s,c,p,k,g){const i=t("DocDiagram");return l(),n("div",null,[s[0]||(s[0]=e("",12)),o(i,{src:"/diagrams/tailscale-code-map.en.svg",alt:"This layered architecture diagram answers one question: after a tailscale command leaves the terminal, which processes and packages does it pass through before it reaches WireGuard, and where do the control plane and the relay attach? From top to bottom: the tailscale command line, whose source lives in cmd/tailscale/cli; the local socket, a Unix socket or a Windows named pipe implemented by safesocket; the LocalAPI HTTP server, made of ipn/ipnserver and ipn/localapi; LocalBackend, in ipn/ipnlocal; wgengine, which contains router, filter, and netstack; magicsock, in wgengine/magicsock; and finally wireguard-go, a dependency outside the repository that sends and receives over UDP. The arrows show the direction of calls and data. The command line sends HTTP requests to the LocalAPI over the local socket, and requests only go from the command line to the daemon. The LocalAPI first checks the caller's permission, read-only or read-write, and then calls LocalBackend. LocalBackend passes the network map and packet filter rules down to wgengine. wgengine hands endpoints and path selection to magicsock. magicsock encrypts and decrypts with wireguard-go. The LocalAPI listens only on the local socket and is never exposed. On the left is the control plane: control/controlclient makes long-polling requests to the coordination server, the coordination server sends the network map back, and controlclient then calls back into LocalBackend; this line carries only public keys, addresses, and policy, and the coordination server is not on the data path. On the right is the relay: magicsock connects to DERP servers through derp and derp/derphttp in order to negotiate connections and to fall back to relaying; DERP relays only encrypted packets. This diagram leaves out the internals of Peer Relay and Tailnet Lock, and the further modules inside each package.",width:960,lang:"en"}),s[1]||(s[1]=e("",100))])}const b=a(h,[["render",r]]);export{m as __pageData,b as default};
